package com.gerenciadorrural.modules.herd.application;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.gerenciadorrural.modules.herd.domain.*;
import com.gerenciadorrural.shared.tenancy.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import java.time.*; import java.util.*;

@Service public class ManageHerdReproduction {
 private static final Set<String> WRITE=Set.of("OWNER","ADMIN","MANAGER","OPERATOR"), TERMINATE=Set.of("OWNER","ADMIN","MANAGER");
 private final TenantTransactionExecutor tx; private final HerdAnimalProfileRepository animals; private final HerdReproductionRepository pregnancies; private final HerdAnimalWriteRepository animalWriter; private final MaternalRelationRepository maternal; private final AnimalEventRepository events; private final ObjectMapper json; private final Clock clock; private final int gestationDays;
 public ManageHerdReproduction(TenantTransactionExecutor tx,HerdAnimalProfileRepository animals,HerdReproductionRepository pregnancies,HerdAnimalWriteRepository animalWriter,MaternalRelationRepository maternal,AnimalEventRepository events,ObjectMapper json,Clock clock,@Value("${herd.reproduction.default-gestation-days:283}") int gestationDays){this.tx=tx;this.animals=animals;this.pregnancies=pregnancies;this.animalWriter=animalWriter;this.maternal=maternal;this.events=events;this.json=json;this.clock=clock;this.gestationDays=gestationDays;}
 public HerdReproductionRepository.Pregnancy breed(TenantContext c,UUID motherId,Breeding x){if(!WRITE.contains(c.role()))throw new HerdMovementForbiddenException();if(x==null||x.operationId()==null||x.expectedMotherVersion()<0||x.serviceType()==null||x.serviceOn()==null||x.serviceOn().isAfter(LocalDate.now(clock).plusDays(1)))bad();LocalDate expected=x.expectedCalvingOn()==null?x.serviceOn().plusDays(gestationDays):x.expectedCalvingOn();if(!expected.isAfter(x.serviceOn()))bad();String payload=canonical(x,expected);return tx.execute(c,()->{events.lockOperation(c.tenantId(),c.farmId(),x.operationId());var replay=pregnancies.findByOperation(c.tenantId(),c.farmId(),x.operationId());if(replay.isPresent()){if(!replay.get().commandPayload().equals(payload))throw new HerdOperationIdempotencyConflictException();return replay.get();}var mother=animals.findByIdForCorrection(c.tenantId(),c.farmId(),motherId).orElseThrow(HerdAnimalNotFoundException::new);if(mother.version()!=x.expectedMotherVersion())throw new HerdAnimalVersionConflictException();if(mother.status()!=HerdAnimalStatus.ACTIVE||mother.sex()!=HerdAnimalSex.FEMALE||(mother.birthDate()!=null&&x.serviceOn().isBefore(mother.birthDate())))throw new HerdLifecycleConflictException();var p=new HerdReproductionRepository.Pregnancy(UUID.randomUUID(),c.tenantId(),c.farmId(),motherId,x.serviceType(),x.serviceOn(),text(x.sireReference(),160),expected,PregnancyStatus.POSSIBLE,null,null,null,null,x.operationId(),payload,0);try{p=pregnancies.insert(p);}catch(org.springframework.dao.DataIntegrityViolationException e){throw new HerdLifecycleConflictException();}var changed=animals.touch(c.tenantId(),c.farmId(),motherId,x.expectedMotherVersion()).orElseThrow(HerdAnimalVersionConflictException::new);events.record(c.tenantId(),c.farmId(),motherId,AnimalEventType.BREEDING_RECORDED,x.operationId(),c.userId(),x.serviceOn(),changed.version(),new BreedingEventDetails(p.id(),p.serviceType(),p.serviceOn(),p.expectedCalvingOn(),p.sireReference(),text(x.notes(),1000)));return p;});}
 public HerdReproductionRepository.Pregnancy confirm(TenantContext c,UUID id,Transition x){return transition(c,id,x,PregnancyStatus.CONFIRMED,null,WRITE,AnimalEventType.PREGNANCY_CONFIRMED);}
 public HerdReproductionRepository.Pregnancy terminate(TenantContext c,UUID id,Transition x,PregnancyTerminationReason reason){if(reason==null)bad();return transition(c,id,x,PregnancyStatus.TERMINATED,reason,TERMINATE,AnimalEventType.PREGNANCY_ENDED);}
 public CalvingResult calve(TenantContext c,UUID motherId,Calving x){if(!TERMINATE.contains(c.role())||x==null||x.operationId()==null||x.expectedMotherVersion()<0||x.calvedOn()==null||x.calfId()==null||x.identification()==null||x.sex()==null)bad();return tx.execute(c,()->{events.lockOperation(c.tenantId(),c.farmId(),x.operationId());var prior=events.findByOperation(c.tenantId(),c.farmId(),x.operationId(),AnimalEventType.CALVED);if(prior.isPresent()){if(!(prior.get().details() instanceof CalvingEventDetails d)||!prior.get().animalId().equals(motherId)||!Objects.equals(d.pregnancyId(),x.pregnancyId())||!d.calfAnimalId().equals(x.calfId())||!Objects.equals(d.calvedOn(),x.calvedOn())||prior.get().resultingVersion()-1!=x.expectedMotherVersion())throw new HerdOperationIdempotencyConflictException();var calf=animals.findById(c.tenantId(),c.farmId(),d.calfAnimalId()).orElseThrow(HerdOperationIdempotencyConflictException::new);if(!calf.identification().equals(text(x.identification(),100))||!Objects.equals(calf.name(),x.name()==null?null:text(x.name(),255))||calf.sex()!=x.sex()||!Objects.equals(calf.birthDate(),x.birthDate()))throw new HerdOperationIdempotencyConflictException();if(x.pregnancyId()!=null&&pregnancies.find(c.tenantId(),c.farmId(),x.pregnancyId(),false).filter(p->p.status()==PregnancyStatus.CALVED&&p.calfAnimalId().equals(d.calfAnimalId())&&(x.expectedPregnancyVersion()==null||p.version()==x.expectedPregnancyVersion()+1)).isEmpty())throw new HerdOperationIdempotencyConflictException();return new CalvingResult(d.calfAnimalId(),prior.get().resultingVersion(),d.pregnancyId());}var mother=animals.findByIdForCorrection(c.tenantId(),c.farmId(),motherId).orElseThrow(HerdAnimalNotFoundException::new);if(mother.version()!=x.expectedMotherVersion()||mother.status()!=HerdAnimalStatus.ACTIVE||mother.sex()!=HerdAnimalSex.FEMALE)throw new HerdLifecycleConflictException();HerdReproductionRepository.Pregnancy pregnancy=null;if(x.pregnancyId()!=null){pregnancy=pregnancies.find(c.tenantId(),c.farmId(),x.pregnancyId(),true).orElseThrow(HerdAnimalNotFoundException::new);if(!pregnancy.motherAnimalId().equals(motherId)||pregnancy.status()!=PregnancyStatus.POSSIBLE&&pregnancy.status()!=PregnancyStatus.CONFIRMED||(x.expectedPregnancyVersion()!=null&&pregnancy.version()!=x.expectedPregnancyVersion()))throw new HerdLifecycleConflictException();}var calf=new NewHerdAnimal(x.calfId(),c.tenantId(),c.farmId(),text(x.identification(),100),x.name()==null?null:text(x.name(),255),x.sex(),x.birthDate());HerdAnimalSummary created;try{created=animalWriter.insert(calf).animal().orElseThrow(HerdAnimalIdempotencyConflictException::new);}catch(HerdAnimalWriteConflictException e){throw new HerdAnimalIdentificationConflictException();}maternal.insert(c.tenantId(),motherId,created.id(),x.pregnancyId());if(pregnancy!=null)pregnancies.transition(c.tenantId(),c.farmId(),pregnancy.id(),pregnancy.version(),PregnancyStatus.CALVED,x.calvedOn(),null,created.id()).orElseThrow(HerdLifecycleConflictException::new);var touched=animals.touch(c.tenantId(),c.farmId(),motherId,x.expectedMotherVersion()).orElseThrow(HerdAnimalVersionConflictException::new);events.record(c.tenantId(),c.farmId(),created.id(),AnimalEventType.CREATED,null,c.userId(),null,0,new CreatedEventDetails(created.identification(),created.name(),created.sex().name(),created.birthDate()));events.record(c.tenantId(),c.farmId(),motherId,AnimalEventType.CALVED,x.operationId(),c.userId(),x.calvedOn(),touched.version(),new CalvingEventDetails(x.pregnancyId(),created.id(),x.calvedOn()));events.record(c.tenantId(),c.farmId(),created.id(),AnimalEventType.BORN,x.operationId(),c.userId(),x.calvedOn(),0,new BornEventDetails(motherId,x.pregnancyId(),x.calvedOn()));return new CalvingResult(created.id(),touched.version(),x.pregnancyId());});}
 private HerdReproductionRepository.Pregnancy transition(TenantContext c,UUID id,Transition x,PregnancyStatus target,PregnancyTerminationReason reason,Set<String> roles,AnimalEventType event){if(!roles.contains(c.role()))throw new HerdMovementForbiddenException();if(x==null||x.operationId()==null||x.expectedVersion()<0||x.occurredOn()==null)bad();return tx.execute(c,()->{events.lockOperation(c.tenantId(),c.farmId(),x.operationId());var replay=events.findByOperation(c.tenantId(),c.farmId(),x.operationId(),event);if(replay.isPresent()){if(!(replay.get().details() instanceof PregnancyEventDetails d)||!d.pregnancyId().equals(id)||!Objects.equals(d.occurredOn(),x.occurredOn())||!Objects.equals(d.terminationReason(),reason)||replay.get().resultingVersion()!=x.expectedVersion()+1)throw new HerdOperationIdempotencyConflictException();return pregnancies.find(c.tenantId(),c.farmId(),id,false).filter(p->p.status()==target&&p.version()==x.expectedVersion()+1).orElseThrow(HerdOperationIdempotencyConflictException::new);}var p=pregnancies.find(c.tenantId(),c.farmId(),id,true).orElseThrow(HerdAnimalNotFoundException::new);if(p.version()!=x.expectedVersion()||p.status()!=(target==PregnancyStatus.CONFIRMED?PregnancyStatus.POSSIBLE:p.status()))throw new HerdLifecycleConflictException();if(target==PregnancyStatus.TERMINATED&&p.status()!=PregnancyStatus.POSSIBLE&&p.status()!=PregnancyStatus.CONFIRMED)throw new HerdLifecycleConflictException();var result=pregnancies.transition(c.tenantId(),c.farmId(),id,x.expectedVersion(),target,x.occurredOn(),reason,null).orElseThrow(HerdLifecycleConflictException::new);events.record(c.tenantId(),c.farmId(),p.motherAnimalId(),event,x.operationId(),c.userId(),x.occurredOn(),result.version(),new PregnancyEventDetails(id,x.occurredOn(),reason));return result;});}
 private String canonical(Object x,LocalDate expected){try{return json.writeValueAsString(Map.of("command",x,"expectedCalvingOn",expected));}catch(Exception e){throw new IllegalStateException(e);}} private static String text(String x,int max){if(x==null)return null;String v=x.strip();if(v.isEmpty()||v.indexOf('\0')>=0||v.codePointCount(0,v.length())>max)bad();return v;}private static void bad(){throw new HerdAnimalCommandInvalidException();}
 public record Breeding(UUID operationId,long expectedMotherVersion,ReproductionServiceType serviceType,LocalDate serviceOn,String sireReference,LocalDate expectedCalvingOn,String notes){} public record Transition(UUID operationId,long expectedVersion,LocalDate occurredOn){} public record Calving(UUID operationId,long expectedMotherVersion,UUID pregnancyId,Long expectedPregnancyVersion,LocalDate calvedOn,UUID calfId,String identification,String name,HerdAnimalSex sex,LocalDate birthDate){} public record CalvingResult(UUID calfAnimalId,long resultingMotherVersion,UUID pregnancyId){}
}
